<?php $this->servers->_display('pending', $viewData); ?>
<section class="card"><h2>Servers</h2><?php if (!$inventory['servers'] && !$pending_servers): ?><p>No servers connected yet. <a href="/servers">Connect your first server</a>.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Server</th><th>Address</th><th>Readiness</th></tr></thead><tbody><?php foreach ($inventory['servers'] as $server): ?><tr><td><?= $e($server['id']) ?></td><td><?= $e($server['host']) ?></td><td><?= $e($server['application_ready']?'Ready':implode(', ',$server['missing'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
